#!/usr/bin/env python3
from __future__ import annotations

import re
import sys
import json
from pathlib import Path


ROOT = Path(__file__).resolve().parents[2]
HTML_ROOT = ROOT / "app" / "src" / "main" / "assets" / "mhxx"
HTML_DIRS = ("data", "ida", "index")
SUMMARY_FILES = (
    ROOT / "temp" / "summary" / "cat_rice_index.json",
    ROOT / "temp" / "summary" / "猫饭技能.json",
    ROOT / "temp" / "summary" / "equip" / "equip_detail.json",
    ROOT / "temp" / "summary" / "equip" / "equips.json",
)
KANA_SEQUENCE_RE = re.compile(r"[ぁ-んァ-ヶー]+")
NEGATIVE_SKILL_RE = re.compile(r"mainasu的(.+?)技能wo持tteiru防具ha非表示nishiteimasu。")


def load_cat_rice_name_replacements() -> list[tuple[str, str]]:
    cat_rice_path = ROOT / "temp" / "translated" / "cat_rice.json"
    data = json.loads(cat_rice_path.read_text(encoding="utf-8-sig"))
    pairs: list[tuple[str, str]] = []
    for source, translated in data.get("name", {}).items():
        pairs.append((source, translated))
        pairs.append((source.replace("ネコ", "猫"), translated))
        pairs.append((source.replace("的", "之"), translated))
        pairs.append((source.replace("ネコ", "猫").replace("的", "之"), translated))
    return pairs


CAT_RICE_NAME_REPLACEMENTS = load_cat_rice_name_replacements()


def load_weapon_name_replacements() -> list[tuple[str, str]]:
    weapon_dir = ROOT / "temp" / "translated" / "weapon"
    pairs: list[tuple[str, str]] = []
    for path in sorted(weapon_dir.glob("*.json")):
        if path.name.endswith("TransBean.json"):
            continue
        data = json.loads(path.read_text(encoding="utf-8-sig"))
        for source, translated in data.items():
            if source == "速":
                continue
            if source != translated:
                pairs.append((source, translated))
    pairs.sort(key=lambda item: len(item[0]), reverse=True)
    return pairs


WEAPON_NAME_REPLACEMENTS = load_weapon_name_replacements()

