    ("溶岩wo带biru炎戈龙的力量持tsu腕部装备。武器ni負担wo与ezu立chi回ruko与gade色ru。", "这件腕部装备拥有携带熔岩的炎戈龙之力。既不会成为武器负担，又能灵活周旋。"),
    ("溶岩wo带biru炎戈龙的力量持tsu腰部装备。体皮ni付着shita溶岩ga坚牢sawo生mi出su。", "这件腰部装备拥有携带熔岩的炎戈龙之力。附着在体表的熔岩会化作坚实防护。"),
    ("溶岩wo带biru炎戈龙的力量持tsu脚部装备。火山的中wo歩kuko与ni適shiteiru。", "这件脚部装备拥有携带熔岩的炎戈龙之力，非常适合在火山中行走。"),
    ("白电龙的素材wo継gi合wasete作rareta片手剑。獲物ni苦痛wo与eru事wo目的ni开发sareta。", "将白电龙素材拼接打造而成的片手剑。其开发目的就是带给猎物极致痛苦。"),
    ("黑狼鸟的素材kara作rareta黑色剑。研gi澄masareta刃ha铁sura易々与切ri裂ku。", "以黑狼鸟素材打造的黑色之剑。磨砺至极的剑刃，连钢铁都能轻易斩开。"),
    ("雌火龙的素材wo用ite作rareta深绿色飞龙刀。高i鋭sa与、威力量两立shita业物dearu。", "以雌火龙素材打造而成的深绿色飞龙刀，兼具锐利度与威力，是一把优良武器。"),
    ("赤甲兽长枪<br>標的he向katte一直線ni伸bi、急所wo突ku赤甲兽的槍。赤色甲壳ga獲物wo睨mi付keru。", "赤甲兽长枪<br>会朝目标笔直伸出并贯穿要害的赤甲兽之枪。赤红甲壳仿佛正死死盯住猎物。"),
    ("赤甲兽之扫<br>赤甲兽长枪最终强化版。抜群的伸縮素材带来的鋭i突刺de、瞬ku間ni獲物wo貫ku。", "赤甲兽之扫<br>赤甲兽长枪的最终强化版。凭借伸缩素材带来的锐利突刺，能在瞬间贯穿猎物。"),
    ("麻蕈刺枪<br>麻痹性的蘑菇wo大胆ni用ita独创的之槍。斩込mu度ni獲物ni麻痹毒gasuri込mareteiku。", "麻蕈刺枪<br>大胆使用麻痹蘑菇打造的原创长枪。每次斩入猎物体内时，都会将麻痹毒一点点渗进去。"),
    ("鬼神铳枪<br>金狮子的猛々shii愤怒ga宿ru銃槍。容赦之i突刺wo繰ri出shi獲物ni雷轰的一击放出。", "鬼神铳枪<br>寄宿着金狮子狂暴怒意的铳枪。会毫不留情地连续突刺，并向猎物轰出雷鸣般的一击。"),
    ("艾露猫大炮<br>白猫wo模shita木製的大砲。zunguri与shita形状ga、何与moie之i可愛sawo演出。", "艾露猫大炮<br>仿照白猫打造的木制大炮。圆滚滚的外形营造出难以言喻的可爱感。"),
    ("冰霜刃<br>千年以上昔的地层kara取reta冰结晶wo使用。长色年月wo経ta结晶ha決shite溶kehashi之i。", "冰霜刃<br>使用从千年以上前地层中取出的冰结晶打造。历经漫长岁月的结晶绝不会轻易融化。"),
    ("moe之i垃圾", "不可燃垃圾"),
    ("赤甲兽的甲壳wo用ita脚部装备。炎ni映eru红色装甲ha火的精灵的双脚的具现。", "使用赤甲兽甲壳打造的脚部装备。映照火焰的红色装甲，仿佛火焰精灵双足的具现。"),
