    ("二tsu名持chi的怪物。通常种与違i体色ya模様之doga异之ru。susamajii炎属性攻击wo持tsu。", "二名怪物。与通常种不同，体色和花纹都有变化，并拥有惊人的火属性攻击。"),
    ("二tsu名持chi的怪物。尾巴的毒的棘de紫煙wo起koshi舞i散raseru。", "二名怪物。会用尾巴上的毒棘扬起并散播紫色毒烟。"),
    ("二tsu名持chi的怪物。通常时yorimo凶暴ni之ri、攻击力appushiteiru。", "二名怪物。比通常种更加凶暴，攻击力也有所提升。"),
    ("二tsu名持chi的怪物。分厚i大盾wo左的大鋏ni备eteiru。mata強力之水属性的buresu攻击wo放tsu。", "二名怪物。左侧大钳配备了厚重巨盾，还会放出强力的水属性吐息攻击。"),
    ("二tsu名持chi的怪物。岩穿鬼蛙的牙ha通常种与比bete异常ni发们shiteiru。", "二名怪物。岩穿鬼蛙的牙齿相比通常种异常发达。"),
    ("二tsu名持chi的怪物。通常种与違i白i紋様ga入tteiru。尾巴de横扫、白i衝击波wo飞basu。", "二名怪物。与通常种不同，身上带有白色纹样。会用尾巴横扫并放出白色冲击波。"),
    ("二tsu名持chi的怪物。通常种与違i金色的光woma与tteiru。绿色的雷光wo缠u状态moaru。", "二名怪物。与通常种不同，身上缠绕着金色光辉，有时还会进入缠绕绿色雷光的状态。"),
    ("二tsu名持chi的怪物。", "二名怪物。"),
    ("持武时ni攻击受到而不会反击的狩技", "持武时受到攻击也不会反击的狩技"),
    ("精准回避后时按 X 可一文字斩、该后Rde气刃无双斩", "精准回避后按 X 可使出一文字斩，之后按 R 可接气刃无双斩"),
    ("武器振ri回shita回旋力量利用shite強力之一击", "利用武器挥舞时产生的回旋力量，发动强力一击"),
    ("怪物挑衅shite一定时间自分会更容易成为目标", "挑衅怪物，使自己在一定时间内更容易成为目标"),
    ("强袭以外的突刺攻击的3段目ha伤害是高ku后仰无效之多段攻击可以使用", "强袭以外的突刺攻击第 3 段为高伤害且后仰无效的多段攻击。"),
    ("空中步de踩踏跳跃后X进行跳跃强突刺", "空中步踩踏跳跃后按 X 可使出跳跃强突刺"),
    ("R　或者　抜刀状态deR＋X　或者　纳刀移动中按 R＋X+A", "R，或拔刀状态按 R + X，或纳刀移动中按 R + X + A"),
