def normalize_visible_mixed_text(text: str) -> str:
    for source, target in VISIBLE_TOKEN_REPLACEMENTS:
        text = text.replace(source, target)
    text = re.sub(r'(?<=\d)he(?=<|$)', '', text)
    text = text.replace("派生1he", "派生1")
    text = text.replace("派生2he", "派生2")
    text = text.replace("长枪1he", "长枪1")
    text = text.replace("长枪2he", "长枪2")
    text = text.replace("铳枪1he", "铳枪1")
    text = text.replace("铳枪2he", "铳枪2")
    text = text.replace("狩猎笛1he", "狩猎笛1")
    text = text.replace("狩猎笛2he", "狩猎笛2")
    text = text.replace("斩击斧1he", "斩击斧1")
    text = text.replace("斩击斧2he", "斩击斧2")
    text = text.replace("大锤1he", "大锤1")
    text = text.replace("大锤2he", "大锤2")
    text = text.replace("弓1he", "弓1")
    text = text.replace("弓2he", "弓2")
    text = text.replace("轻弩1he", "轻弩1")
    text = text.replace("轻弩2he", "轻弩2")
    text = text.replace("重弩1he", "重弩1")
    text = text.replace("重弩2he", "重弩2")
    text = re.sub(r'(?<=[一-龥A-Za-z0-9])of(?=[一-龥A-Za-z0-9])', '之', text)
    return text


def replace_visible_of_or(match: re.Match[str]) -> str:
    return normalize_visible_mixed_text(match.group(0))


def apply_normalized_replacements(text: str, replacements: list[tuple[str, str]]) -> str:
    updated = text
    for source, target in replacements:
        normalized = normalize_visible_mixed_text(source)
        updated = updated.replace(normalized, target)
    return updated


